<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Order; use Illuminate\Http\Request; use Illuminate\Support\Str;
class WhatsAppController extends Controller { public function order(Request $r, Order $order) { $phone=config('services.whatsapp.store_number'); abort_unless($phone,503,'Nomor WhatsApp toko belum dikonfigurasi.'); $token=$r->header('X-Cart-Token'); if($order->user_id && $r->user('sanctum')?->id!==$order->user_id) abort(403); if(!$order->user_id && !hash_equals((string)$order->guest_token,(string)$token)) abort(403); $order->load('items'); foreach($order->items as $item) $order->whatsAppClicks()->create(['book_id'=>$item->book_id,'guest_token'=>$token]); $lines=$order->items->map(fn($i)=>"- {$i->title} x{$i->quantity} (Rp".number_format($i->subtotal,0,',','.').')')->implode("\n"); $message="Halo Bukupagi, saya ingin menanyakan order {$order->number}.\n{$lines}\nTotal: Rp".number_format($order->grand_total,0,',','.'); return response()->json(['data'=>['url'=>'https://wa.me/'.$phone.'?text='.rawurlencode($message)]]); } }
